public final class EtfMonitorScreen extends LinearLayout {
 public interface Host{void openChart(String exactEtfId,String period)throws Exception;default boolean supportsRefresh(){return false;}default void refresh(String token,JSONObject selection)throws Exception{throw new Exception("来源刷新未接线");}default void cancelRefresh(String token)throws Exception{}default boolean supportsExport(){return false;}default void exportEvidence(byte[] evidence)throws Exception{throw new Exception("导出未接线");}}
 private String chosenDay="";private final Button calendar;
 private final Host host;private final EtfMonitorStore store;private JSONObject archive,current;private String selected="",historical="",token="",lastFilters="";private int page,viewMode,visibleCount;private boolean updating,active=true,closed,dark,refreshAvailable;
 private final TextView message,pager,detail,raw,archiveInfo;private final EditText search;private final Spinner sort,availability,history,period;private final LinearLayout filtersPanel,rowsPanel,detailPanel,rawPanel;private final ScrollView scroll;private final Button refreshQuotes,refreshMinute,stop,previous,next,open;private List<String> historyIds=new ArrayList<>();
 private static final String[] SORTS={"changePercent-desc","changePercent-asc","amount-desc","price-desc","id-asc"},AVAILABILITY={"all","quoted","unquoted"},PERIODS={"quote","minute","day","week","month","year"};
 public EtfMonitorScreen(Context context,File dedicatedArchive,Host host){super(context);this.host=host;store=new EtfMonitorStore(dedicatedArchive);refreshAvailable=host!=null&&host.supportsRefresh();setTag("etfMonitorPage");setOrientation(VERTICAL);setSaveEnabled(false);setImportantForAutofill(View.IMPORTANT_FOR_AUTOFILL_NO_EXCLUDE_DESCENDANTS);message=new TextView(context);message.setText("本机ETF目录 · 时点逐项；成交额不是申赎");message.setMaxLines(2);addView(message,new LayoutParams(-1,-2));LinearLayout tools=new LinearLayout(context);addView(tools,new LayoutParams(-1,dp(48)));Button filterButton=button("筛选/历史","etfMonitorFilters");refreshQuotes=button("本页报价","etfMonitorRefreshQuotes");refreshMinute=button("选中分钟","etfMonitorRefreshMinute");stop=button("取消","etfMonitorCancel");for(Button b:new Button[]{filterButton,refreshQuotes,refreshMinute,stop})tools.addView(b,new LayoutParams(0,-1,1));scroll=new ScrollView(context);addView(scroll,new LayoutParams(-1,0,1));LinearLayout content=new LinearLayout(context);content.setOrientation(VERTICAL);scroll.addView(content);filtersPanel=new LinearLayout(context);filtersPanel.setOrientation(VERTICAL);content.addView(filtersPanel);filtersPanel.setVisibility(GONE);
  sort=selector("排序","etfMonitorSort",new String[]{"涨幅优先","跌幅优先","成交额优先","价格优先","完整ID顺序"});availability=selector("范围","etfMonitorAvailability",new String[]{"全部本机目录","有报价","报价缺失"});search=new EditText(context);search.setTag("etfMonitorSearch");search.setSaveEnabled(false);search.setSingleLine(true);search.setFilters(new InputFilter[]{new InputFilter.LengthFilter(120)});search.setHint("名称 / 完整ETF身份");filtersPanel.addView(search,new LayoutParams(-1,dp(48)));history=selector("本机历史","etfMonitorHistory",new String[]{"当前本机缓存"});historyIds.add("");LinearLayout dateTools=new LinearLayout(context);filtersPanel.addView(dateTools);
  calendar=button("日历","etfMonitorDate");dateTools.addView(calendar,new LayoutParams(0,dp(48),1));
  Button latest=button("当前观测","etfMonitorCurrent");dateTools.addView(latest,new LayoutParams(0,dp(48),1));
  calendar.setOnClickListener(v->pickDate());latest.setOnClickListener(v->{if(!usable())return;try{historical="";current=EtfMonitorModel.frame(archive,"");syncCalendar();historyOptions();render();message.setText("当前本机观测；来源时间逐项显示");}catch(Exception e){fail();}});
  period=selector("原生行情周期","etfMonitorPeriod",new String[]{"报价","分时","日K","周K","月K","年K"});archiveInfo=new TextView(context);archiveInfo.setTextIsSelectable(true);filtersPanel.addView(archiveInfo);Button export=button("导出当前筛选证据","etfMonitorExport");filtersPanel.addView(export,new LayoutParams(-1,dp(48)));Button listView=button("返回目录","etfMonitorList"),rawView=button("完整白名单状态","etfMonitorRawButton");filtersPanel.addView(listView,new LayoutParams(-1,dp(48)));filtersPanel.addView(rawView,new LayoutParams(-1,dp(48)));
  rowsPanel=new LinearLayout(context);rowsPanel.setTag("etfMonitorRows");rowsPanel.setOrientation(VERTICAL);content.addView(rowsPanel);detailPanel=new LinearLayout(context);detailPanel.setOrientation(VERTICAL);content.addView(detailPanel);detail=new TextView(context);detail.setTextIsSelectable(true);detailPanel.addView(detail);rawPanel=new LinearLayout(context);rawPanel.setOrientation(VERTICAL);content.addView(rawPanel);raw=new TextView(context);raw.setTag("etfMonitorRaw");raw.setTextIsSelectable(true);rawPanel.addView(raw);LinearLayout footer=new LinearLayout(context);addView(footer,new LayoutParams(-1,dp(48)));previous=button("上一页","etfMonitorPrevious");next=button("下一页","etfMonitorNext");open=button("原生行情","etfMonitorOpen");pager=new TextView(context);pager.setGravity(17);footer.addView(previous,new LayoutParams(0,-1,1));footer.addView(pager,new LayoutParams(0,-1,2));footer.addView(open,new LayoutParams(0,-1,1));footer.addView(next,new LayoutParams(0,-1,1));
  try{archive=store.read();current=EtfMonitorModel.frame(archive,"");}catch(Exception e){try{archive=EtfMonitorModel.emptyArchive();current=EtfMonitorModel.emptySnapshot();}catch(Exception ignored){}fail();}historyOptions();render();
  sort.setOnItemSelectedListener(filterListener());availability.setOnItemSelectedListener(filterListener());search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int start,int count,int after){}public void onTextChanged(CharSequence s,int start,int before,int count){filterChanged();}public void afterTextChanged(Editable e){}});history.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onItemSelected(AdapterView<?> p,View v,int position,long id){if(updating||position<0||position>=historyIds.size())return;String chosen=historyIds.get(position);if(chosen.equals(historical))return;try{historical=chosen;current=EtfMonitorModel.frame(archive,historical);syncCalendar();page=0;selected="";viewMode=0;render();message.setText(historical.isEmpty()?"当前本机缓存；不是全市场同刻榜单":"本机历史只读；原生行情打开已有功能，不改历史");}catch(Exception e){fail();}}public void onNothingSelected(AdapterView<?> p){}});
  filterButton.setOnClickListener(v->{if(usable())filtersPanel.setVisibility(filtersPanel.getVisibility()==VISIBLE?GONE:VISIBLE);});refreshQuotes.setOnClickListener(v->request("quote"));refreshMinute.setOnClickListener(v->request("minute"));stop.setOnClickListener(v->cancel());previous.setOnClickListener(v->{if(usable()&&page>0){--page;render();}});next.setOnClickListener(v->{if(usable()){++page;render();}});open.setOnClickListener(v->{if(usable()&&host!=null&&!selected.isEmpty())try{host.openChart(selected,PERIODS[Math.max(0,period.getSelectedItemPosition())]);}catch(Exception e){fail();}});listView.setOnClickListener(v->{if(usable()){viewMode=0;renderMode();}});rawView.setOnClickListener(v->{if(usable()){viewMode=viewMode==2?1:2;renderMode();}});export.setOnClickListener(v->{if(!usable())return;try{byte[] bytes=exportEvidence();if(host!=null&&host.supportsExport())host.exportEvidence(bytes);else{android.content.ClipboardManager clipboard=(android.content.ClipboardManager)getContext().getSystemService(Context.CLIPBOARD_SERVICE);clipboard.setPrimaryClip(ClipData.newPlainText("本机ETF非敏感观测",new String(bytes,StandardCharsets.UTF_8)));message.setText("已复制筛选观测；未请求数据源");}}catch(Exception e){fail();}});setDarkTheme(false);
 }
 private void syncCalendar(){chosenDay=EtfMonitorModel.sourceDay(current);calendar.setText(chosenDay.isEmpty()?"日历 · 来源日未知":chosenDay);}
 private void pickDate(){if(!usable())return;java.time.LocalDate initial=TradingDaySelection.parse(chosenDay);if(initial==null)initial=java.time.LocalDate.now(java.time.ZoneOffset.ofHours(8));new android.app.DatePickerDialog(getContext(),(picker,y,m,d)->selectDate(java.time.LocalDate.of(y,m+1,d)),initial.getYear(),initial.getMonthValue()-1,initial.getDayOfMonth()).show();}
 void selectDate(java.time.LocalDate chosen){if(!usable())return;cancel();try{String id=EtfMonitorModel.frameOnOrBefore(archive,chosen);historical=id.isEmpty()?"no-saved-day":id;current=id.isEmpty()?EtfMonitorModel.emptySnapshot():EtfMonitorModel.frame(archive,id);chosenDay=chosen.toString();calendar.setText(chosenDay);page=0;selected="";viewMode=0;historyOptions();render();message.setText(TradingDaySelection.recordCaption(chosen,EtfMonitorModel.sourceDay(current)));message.setMaxLines(3);}catch(Exception e){fail();}}
 private boolean usable(){return active&&!closed;}
 private int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
 private Button button(String text,String tag){Button b=new Button(getContext());b.setText(text);b.setTag(tag);b.setTextSize(12);b.setPadding(dp(3),0,dp(3),0);b.setMinHeight(dp(48));return b;}
 private Spinner selector(String label,String tag,String[] labels){TextView title=new TextView(getContext());title.setText(label);filtersPanel.addView(title);Spinner s=new Spinner(getContext());s.setTag(tag);adapter(s,Arrays.asList(labels));filtersPanel.addView(s,new LayoutParams(-1,dp(48)));return s;}
 private void adapter(Spinner s,List<String> labels){ArrayAdapter<String> a=new ArrayAdapter<String>(getContext(),android.R.layout.simple_spinner_item,labels){public View getView(int p,View v,android.view.ViewGroup g){View x=super.getView(p,v,g);paint(x);return x;}public View getDropDownView(int p,View v,android.view.ViewGroup g){View x=super.getDropDownView(p,v,g);paint(x);x.setMinimumHeight(dp(48));x.setBackgroundColor(background());return x;}};a.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);s.setAdapter(a);}
 private AdapterView.OnItemSelectedListener filterListener(){return new AdapterView.OnItemSelectedListener(){public void onItemSelected(AdapterView<?> p,View v,int position,long id){filterChanged();}public void onNothingSelected(AdapterView<?> p){}};}
 private JSONObject filters()throws Exception{String choice=SORTS[Math.max(0,sort.getSelectedItemPosition())];return new JSONObject().put("search",search.getText().toString()).put("availability",AVAILABILITY[Math.max(0,availability.getSelectedItemPosition())]).put("sort",choice.substring(0,choice.indexOf('-'))).put("ascending",choice.endsWith("-asc"));}
 private void filterChanged(){if(updating)return;try{String now=filters().toString();if(now.equals(lastFilters))return;page=0;selected="";viewMode=0;render();}catch(Exception e){fail();}}
 private JSONObject selectedItem()throws Exception{JSONArray items=current.getJSONArray("items");for(int n=0;n<items.length();n++)if(items.getJSONObject(n).getString("id").equals(selected))return items.getJSONObject(n);return null;}
 private void historyOptions(){updating=true;try{if(historical.isEmpty())syncCalendar();historyIds=new ArrayList<>();List<String> labels=new ArrayList<>();historyIds.add("");labels.add("当前本机缓存");JSONArray frames=archive.getJSONArray("frames");for(int n=frames.length()-1;n>=0;n--){JSONObject frame=frames.getJSONObject(n);historyIds.add(frame.getString("id"));String sourceDay=EtfMonitorModel.sourceDay(EtfMonitorModel.frame(archive,frame.getString("id")));labels.add("来源 "+(sourceDay.isEmpty()?"未知":sourceDay)+" · 保存 "+frame.getString("storedAt"));}if(!historical.isEmpty()&&!historyIds.contains(historical)){historyIds.add(historical);labels.add("所选日期无可用归档");}adapter(history,labels);int p=historyIds.indexOf(historical);history.setSelection(p<0?0:p);}catch(Exception e){fail();}finally{updating=false;}}
 private void render(){try{JSONObject f=filters();lastFilters=f.toString();JSONArray visible=EtfMonitorModel.rows(current,f);visibleCount=visible.length();page=Math.max(0,Math.min(page,Math.max(0,(visible.length()-1)/24)));rowsPanel.removeAllViews();boolean found=false;for(int n=page*24;n<visible.length()&&n<(page+1)*24;n++){JSONObject r=visible.getJSONObject(n),q=r.getJSONObject("quote");String id=r.getString("id");found|=id.equals(selected);Button row=button(r.getString("name")+" · "+id+"\n价格 "+numeric(q,"price",3)+"；涨幅% "+numeric(q,"changePercent",2)+"；成交额元 "+numeric(q,"amount",2)+"\n来源日 "+(q.optString("tradeDate").isEmpty()?"未知":q.optString("tradeDate")),"etfMonitorRow:"+id);row.setMinHeight(dp(72));row.setSingleLine(false);rowsPanel.addView(row,new LayoutParams(-1,-2));View separator=new View(getContext());separator.setTag("etfMonitorDivider");separator.setBackgroundColor(dark?0xff64748b:0xff94a3b8);rowsPanel.addView(separator,new LayoutParams(-1,dp(1)));row.setOnClickListener(v->{if(usable()){selected=id;viewMode=1;select();}});}if(!found)selected=visible.length()>page*24?visible.getJSONObject(page*24).getString("id"):"";if(visible.length()==0){TextView empty=new TextView(getContext());empty.setText("没有匹配的本机ETF目录项；缺报价不代表停牌或成交额为零。");rowsPanel.addView(empty);}pager.setText((page+1)+"/"+Math.max(1,(visible.length()+23)/24)+" · "+visible.length());previous.setEnabled(page>0);next.setEnabled((page+1)*24<visible.length());JSONObject attempt=archive.getJSONObject("attempt");archiveInfo.setText("仅注入本机目录，不是全市场同刻榜。申赎日报使用已有原生页。\n最近模块尝试："+attempt.optString("status","未知")+" · "+attempt.optString("at","未知")+"\n"+attempt.optString("error","")+"\n本机保存时间与来源时间分开；期货身份/时段未在本模块接入。");select();applyColors(this);}catch(Exception e){fail();}}
 private static String display(JSONObject o,String k){return o.isNull(k)?"—":o.opt(k).toString();}
 private static String numeric(JSONObject o,String k,int decimals){return o.isNull(k)?"—":String.format(Locale.ROOT,"%."+decimals+"f",o.optDouble(k));}
 private void select(){try{JSONObject row=selectedItem();detail.setText(row==null?"报价 / 分钟成交额缺失保持未知。成交额不是申赎或净资金；期货另待接入。":EtfMonitorModel.describe(row));raw.setText(row==null?"":row.toString(2));open.setEnabled(usable()&&host!=null&&row!=null);refreshQuotes.setEnabled(usable()&&refreshAvailable&&token.isEmpty()&&visibleCount>0);refreshMinute.setEnabled(usable()&&refreshAvailable&&token.isEmpty()&&row!=null);stop.setEnabled(!token.isEmpty());renderMode();}catch(Exception e){fail();}}
 private void renderMode(){rowsPanel.setVisibility(viewMode==0?VISIBLE:GONE);detailPanel.setVisibility(viewMode==1?VISIBLE:GONE);rawPanel.setVisibility(viewMode==2?VISIBLE:GONE);scroll.scrollTo(0,0);}
 private void request(String mode){if(!usable()||!refreshAvailable||!token.isEmpty()||host==null)return;try{JSONArray ids=new JSONArray();if(mode.equals("minute")){if(selected.isEmpty())return;ids.put(selected);}else{JSONArray visible=EtfMonitorModel.rows(current,filters());for(int n=page*24;n<visible.length()&&n<(page+1)*24;n++)ids.put(visible.getJSONObject(n).getString("id"));}if(ids.length()==0)return;token=UUID.randomUUID().toString();select();message.setText("仅请求所选ETF / 当前页；来源和取消由主页面处理");host.refresh(token,new JSONObject().put("ids",ids).put("period",mode));}catch(Exception e){if(!token.isEmpty())failRefresh(token,"主页面刷新未完成");else fail();}}
 private void storeSnapshot(JSONObject input)throws Exception{JSONObject safe=EtfMonitorModel.snapshot(input),next=EtfMonitorModel.append(archive,safe,Instant.now().toString());store.save(next,archive.getLong("revision"));archive=next;boolean following=historical.isEmpty();if(following){current=safe;syncCalendar();}historyOptions();render();message.setText(following?"本机ETF观测已保存读回；时点逐项，不保证实时或全市场排名":"新观测已保存；保留当前历史阅读 · "+chosenDay);}
 public void setSnapshot(JSONObject input){if(!usable())return;cancel();try{storeSnapshot(input);}catch(Exception e){fail();}}
 public void acceptSnapshot(String incoming,JSONObject input){if(!usable()||token.isEmpty()||!token.equals(incoming))return;try{storeSnapshot(input);token="";select();}catch(Exception e){failRefresh(incoming,"ETF输入/缓存检查失败");}}
 private void attempt(String status,String reason){try{JSONObject next=EtfMonitorModel.failed(archive,status,Instant.now().toString(),reason);store.save(next,archive.getLong("revision"));archive=next;historyOptions();render();}catch(Exception e){fail();}}
 public void failRefresh(String incoming,String reason){if(token.isEmpty()||!token.equals(incoming))return;token="";attempt("failed",reason);select();message.setText("本次刷新失败，保留原观测与历史；原因见筛选/历史中的尝试记录");}
 public void cancel(){if(token.isEmpty())return;String prior=token;token="";if(host!=null)try{host.cancelRefresh(prior);}catch(Exception ignored){}attempt("cancelled","用户取消；迟到结果不保存");select();message.setText("已取消本模块等待；迟到回调不改缓存 / 历史");}
 public void setRefreshAvailable(boolean value){refreshAvailable=value&&host!=null;select();}
 public void setActive(boolean value){if(!value)cancel();active=value;select();}
 public void close(){cancel();closed=true;active=false;select();}
 public JSONObject saveState(){try{JSONObject f=filters();if(EtfMonitorModel.secret(f.optString("search")))f.put("search","");return new JSONObject().put("schema","native-etf-monitor-ui/v1").put("filters",f).put("selected",selected).put("history",historical).put("chosenDay",chosenDay).put("period",PERIODS[Math.max(0,period.getSelectedItemPosition())]).put("page",page).put("viewMode",viewMode);}catch(Exception e){return new JSONObject();}}
 public void restoreState(JSONObject s){if(!s.optString("schema").equals("native-etf-monitor-ui/v1"))return;updating=true;try{JSONObject f=s.getJSONObject("filters");String choice=f.optString("sort")+"-"+(f.optBoolean("ascending")?"asc":"desc");sort.setSelection(Math.max(0,Arrays.asList(SORTS).indexOf(choice)));availability.setSelection(Math.max(0,Arrays.asList(AVAILABILITY).indexOf(f.optString("availability"))));String text=f.optString("search","");search.setText(text.substring(0,Math.min(120,text.length())));period.setSelection(Math.max(0,Arrays.asList(PERIODS).indexOf(s.optString("period"))));historical=s.optString("history","");current=EtfMonitorModel.frame(archive,historical);chosenDay=s.optString("chosenDay","");if(historical.isEmpty())syncCalendar();else calendar.setText(TradingDaySelection.parse(chosenDay)==null?"日历 · 来源日未知":chosenDay);historyOptions();selected=s.optString("selected","");page=Math.max(0,Math.min(83,s.optInt("page")));viewMode=Math.max(0,Math.min(2,s.optInt("viewMode")));}catch(Exception e){fail();}finally{updating=false;}render();}
 public byte[] exportEvidence()throws Exception{JSONObject out=new JSONObject(current.toString()).put("items",EtfMonitorModel.rows(current,filters())).put("moduleAttempt",archive.getJSONObject("attempt")).put("exportedAt",Instant.now().toString()).put("historicalFrame",historical);return out.toString(2).getBytes(StandardCharsets.UTF_8);}
 public void setHostError(String ignored){fail();}
 private void fail(){message.setText("ETF输入 / 本机独立档案检查未通过；原观测保留，未补造数据");}
 private int background(){return dark?Color.rgb(17,26,40):Color.rgb(245,248,252);}
 private ColorStateList colors(){return new ColorStateList(new int[][]{new int[]{-android.R.attr.state_enabled},new int[]{}},new int[]{dark?Color.rgb(126,145,165):Color.rgb(100,116,139),dark?Color.rgb(235,241,249):Color.rgb(25,41,62)});}
 private void paint(View v){if(v instanceof TextView)((TextView)v).setTextColor(colors());}
 private void applyColors(View v){if("etfMonitorDivider".equals(v.getTag()))v.setBackgroundColor(dark?0xff64748b:0xff94a3b8);paint(v);if(v instanceof Spinner||v instanceof EditText)v.setBackgroundTintList(colors());if(v instanceof Button)v.setBackgroundTintList(ColorStateList.valueOf(dark?Color.rgb(39,55,77):Color.rgb(220,231,245)));if(v instanceof android.view.ViewGroup){android.view.ViewGroup g=(android.view.ViewGroup)v;for(int n=0;n<g.getChildCount();n++)applyColors(g.getChildAt(n));}}
 public void setDarkTheme(boolean value){dark=value;setBackgroundColor(background());applyColors(this);for(Spinner field:new Spinner[]{sort,availability,history,period})if(field.getAdapter() instanceof ArrayAdapter)((ArrayAdapter<?>)field.getAdapter()).notifyDataSetChanged();}
}
